-- Tranche 1 HACCP (temperatures)
-- 1) restaurant_id -> merchant_id
-- 2) soft delete support for zones
-- 3) session-based batch insert support
-- 4) column sizes aligned with prefixed IDs generated by helpers.GeneratePrefixedID

-- =========================
-- haccp_settings
-- =========================
ALTER TABLE haccp_settings
  MODIFY COLUMN id VARCHAR(80) NOT NULL,
  CHANGE COLUMN restaurant_id merchant_id VARCHAR(64) NOT NULL;

ALTER TABLE haccp_settings
  DROP INDEX uq_haccpsettings_restaurant,
  ADD UNIQUE KEY uq_haccpsettings_merchant (merchant_id);

-- =========================
-- temperature_zones
-- =========================
ALTER TABLE temperature_zones
  MODIFY COLUMN id VARCHAR(64) NOT NULL,
  CHANGE COLUMN restaurant_id merchant_id VARCHAR(64) NOT NULL,
  ADD COLUMN enabled TINYINT(1) NOT NULL DEFAULT 1,
  ADD COLUMN deleted_at DATETIME NULL;

ALTER TABLE temperature_zones
  DROP INDEX idx_tempzones_restaurant,
  ADD KEY idx_tempzones_merchant (merchant_id),
  ADD KEY idx_tempzones_merchant_enabled (merchant_id, enabled);

-- =========================
-- temperature_sessions
-- =========================
CREATE TABLE temperature_sessions (
  id         VARCHAR(64) NOT NULL,
  merchant_id VARCHAR(64) NOT NULL,
  created_by VARCHAR(255) NOT NULL,
  enabled    TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_tempsess_merchant_created (merchant_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================
-- temperature_readings
-- =========================
ALTER TABLE temperature_readings
  DROP FOREIGN KEY fk_tempread_zone;

ALTER TABLE temperature_readings
  MODIFY COLUMN id VARCHAR(64) NOT NULL,
  CHANGE COLUMN restaurant_id merchant_id VARCHAR(64) NOT NULL,
  MODIFY COLUMN zone_id VARCHAR(64) NOT NULL,
  ADD COLUMN session_id VARCHAR(64) NOT NULL AFTER id,
  ADD COLUMN comment TEXT NULL AFTER signature,
  ADD COLUMN enabled TINYINT(1) NOT NULL DEFAULT 1;

ALTER TABLE temperature_readings
  DROP INDEX idx_tempread_restaurant_created,
  ADD KEY idx_tempread_merchant_created (merchant_id, created_at),
  ADD KEY idx_tempread_session (session_id),
  ADD KEY idx_tempread_merchant_session (merchant_id, session_id);

ALTER TABLE temperature_readings
  ADD CONSTRAINT fk_tempread_zone FOREIGN KEY (zone_id)
    REFERENCES temperature_zones(id) ON DELETE CASCADE,
  ADD CONSTRAINT fk_tempread_session FOREIGN KEY (session_id)
    REFERENCES temperature_sessions(id) ON DELETE CASCADE;

