  status           ENUM('ok','alert','critical') NOT NULL DEFAULT 'ok',
  photo_url        VARCHAR(512) NULL,
  signature        MEDIUMTEXT NULL,
  comment          TEXT NULL,
  created_by       VARCHAR(255) NOT NULL,
  enabled          TINYINT(1) NOT NULL DEFAULT 1,
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_tempread_merchant_created (merchant_id, created_at),
  KEY idx_tempread_zone (zone_id),
  KEY idx_tempread_session (session_id),
  KEY idx_tempread_merchant_session (merchant_id, session_id),
  CONSTRAINT fk_tempread_zone FOREIGN KEY (zone_id)
    REFERENCES temperature_zones(id) ON DELETE CASCADE,
  CONSTRAINT fk_tempread_session FOREIGN KEY (session_id)
    REFERENCES temperature_sessions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
